/*!
 * Themeasy — Countdown Timer
 *
 * Drives the .tms-countdown-timer widget. Supports:
 *   - Fixed due-date mode (shared deadline for all visitors)
 *   - Evergreen mode (per-visitor offset persisted in local/session/cookie)
 *   - Expire actions: message | hide | redirect
 *   - Tick animations respect prefers-reduced-motion
 *
 * Namespace:    window.Themeasy.countdownTimer
 * Pattern:      IIFE + onDomReady() + boot()
 * Idempotent:   each element is bound at most once; re-init safe in editor.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.countdownTimer = window.Themeasy.countdownTimer || {}

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  function prefersReducedMotion() {
    return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)
  }

  // ------------------------------------------------------------------------
  // Storage drivers (evergreen mode)
  // ------------------------------------------------------------------------

  // Each driver mimics a tiny subset of the Storage interface so we can share
  // the read/write helpers below. All failures are swallowed because Safari in
  // private mode and tracking-prevention modes throw on access.
  const Storage = {
    local: {
      get: function (key) {
        try { return window.localStorage.getItem(key) } catch (e) { return null }
      },
      set: function (key, value) {
        try { window.localStorage.setItem(key, value) } catch (e) { /* noop */ }
      }
    },
    session: {
      get: function (key) {
        try { return window.sessionStorage.getItem(key) } catch (e) { return null }
      },
      set: function (key, value) {
        try { window.sessionStorage.setItem(key, value) } catch (e) { /* noop */ }
      }
    },
    cookie: {
      get: function (key) {
        try {
          const prefix = encodeURIComponent(key) + '='
          const parts = document.cookie ? document.cookie.split(';') : []
          for (let i = 0; i < parts.length; i++) {
            const piece = parts[i].trim()
            if (piece.indexOf(prefix) === 0) {
              return decodeURIComponent(piece.substring(prefix.length))
            }
          }
          return null
        } catch (e) {
          return null
        }
      },
      set: function (key, value) {
        try {
          // 30 days default lifetime; long enough to honour evergreen semantics.
          const maxAge = 60 * 60 * 24 * 30
          document.cookie =
            encodeURIComponent(key) + '=' + encodeURIComponent(value) +
            '; Max-Age=' + maxAge + '; Path=/; SameSite=Lax'
        } catch (e) { /* noop */ }
      }
    }
  }

  function pickDriver(name) {
    return Storage[name] || Storage.local
  }

  // ------------------------------------------------------------------------
  // Core init
  // ------------------------------------------------------------------------

  /**
   * Initialize countdown timers within the given scope.
   *
   * @param {ParentNode} [root=document] Scope to query inside.
   */
  window.Themeasy.countdownTimer.init = function (root) {
    // ------------------------------------------------------------------------
    // Selectors & constants.
    // ------------------------------------------------------------------------
    const SELECTOR_ROOT  = '.tms-countdown-timer'
    const SELECTOR_UNIT  = '.tms-countdown-timer__unit'
    const SELECTOR_VALUE = '.tms-countdown-timer__value'
    const SELECTOR_RING  = '.tms-countdown-timer__ring-progress'
    const UNIT_TICK_CLS  = 'tms-countdown-timer__unit--ticking'

    const MS_SECOND = 1000
    const MS_MINUTE = 60 * MS_SECOND
    const MS_HOUR   = 60 * MS_MINUTE
    const MS_DAY    = 24 * MS_HOUR

    // Denominator for the radial ring of each unit (full cycle before the
    // parent unit ticks down by 1).
    const RING_CAPS = {
      days: 30,         // no natural upper bound; 30 gives a visible rhythm.
      hours: 24,
      minutes: 60,
      seconds: 60
    }

    const scope = root || document

    // ------------------------------------------------------------------------
    // Helpers.
    // ------------------------------------------------------------------------

    /**
     * Parse a number attribute safely, falling back to 0.
     *
     * @param {HTMLElement} el Host element.
     * @param {string} name Attribute name.
     * @returns {number} Parsed value or 0.
     */
    function readNumAttr(el, name) {
      const raw = el.getAttribute(name)
      if (raw === null || raw === '') return 0

      const parsed = parseInt(raw, 10)
      return isNaN(parsed) ? 0 : parsed
    }

    /**
     * Resolve the target timestamp (ms) for the given widget root.
     *
     * Due-date mode: parse the ISO attribute.
     * Evergreen mode: read persisted start from storage (or seed it now) and
     * offset by the configured duration.
     *
     * @param {HTMLElement} rootEl Widget root.
     * @returns {number} Target epoch ms, or 0 when misconfigured.
     */
    function resolveDeadline(rootEl) {
      const mode = rootEl.getAttribute('data-mode') || 'due_date'

      if (mode === 'evergreen') {
        const durationSec = readNumAttr(rootEl, 'data-duration')
        if (durationSec <= 0) return 0

        const storageName = rootEl.getAttribute('data-storage') || 'local'
        const storageKey  = rootEl.getAttribute('data-storage-key') || 'themeasy_countdown_default'
        const driver      = pickDriver(storageName)

        let start = parseInt(driver.get(storageKey), 10)
        if (isNaN(start) || start <= 0) {
          start = Date.now()
          driver.set(storageKey, String(start))
        }

        return start + (durationSec * MS_SECOND)
      }

      // due_date mode.
      const iso = rootEl.getAttribute('data-end-iso')
      if (!iso) return 0

      const parsed = Date.parse(iso)
      return isNaN(parsed) ? 0 : parsed
    }

    /**
     * Break a remaining-milliseconds figure into day/hour/minute/second parts.
     *
     * @param {number} remaining Milliseconds remaining.
     * @returns {{days:number,hours:number,minutes:number,seconds:number}}
     */
    function breakdown(remaining) {
      if (remaining <= 0) {
        return { days: 0, hours: 0, minutes: 0, seconds: 0 }
      }

      const days    = Math.floor(remaining / MS_DAY)
      const hours   = Math.floor((remaining % MS_DAY)    / MS_HOUR)
      const minutes = Math.floor((remaining % MS_HOUR)   / MS_MINUTE)
      const seconds = Math.floor((remaining % MS_MINUTE) / MS_SECOND)

      return { days: days, hours: hours, minutes: minutes, seconds: seconds }
    }

    /**
     * Format a numeric value according to the wrapper's padding setting.
     *
     * Days grow beyond two digits so we only pad when the value is <= 99.
     *
     * @param {number} value Raw value.
     * @param {boolean} pad Whether padding is enabled.
     * @returns {string}
     */
    function formatValue(value, pad) {
      if (!pad || value >= 100) {
        return String(value)
      }
      return value < 10 ? '0' + value : String(value)
    }

    /**
     * Update a single unit's displayed value and (for circles skin) ring.
     *
     * @param {HTMLElement} unit Unit element.
     * @param {string} key Unit key (days/hours/minutes/seconds).
     * @param {number} value Current value.
     * @param {boolean} pad Padding enabled?
     * @param {boolean} animate Whether to pulse the tick class.
     */
    function paintUnit(unit, key, value, pad, animate) {
      const valueEl = unit.querySelector(SELECTOR_VALUE)
      if (!valueEl) return

      const next = formatValue(value, pad)
      if (valueEl.textContent === next) return

      valueEl.textContent = next

      // Update unit data attribute for CSS hooks / tests.
      unit.setAttribute('data-value', String(value))

      // Tick animation (skipped automatically under reduced motion via CSS).
      if (animate) {
        unit.classList.add(UNIT_TICK_CLS)
        window.setTimeout(function () {
          unit.classList.remove(UNIT_TICK_CLS)
        }, 240)
      }

      // Circle ring (only present under the circles skin).
      const ring = unit.querySelector(SELECTOR_RING)
      if (ring) {
        const cap = RING_CAPS[key] || 60
        const clamped = Math.max(0, Math.min(cap, value))
        const degrees = Math.round((clamped / cap) * 360)
        ring.style.setProperty('--progress', String(degrees))
      }
    }

    /**
     * Signal the expire state + trigger the configured action.
     *
     * @param {HTMLElement} rootEl Widget root.
     * @param {Object} instance Internal state bag.
     */
    function onExpire(rootEl, instance) {
      if (instance.expired) return
      instance.expired = true

      rootEl.setAttribute('aria-live', 'polite')

      const action = rootEl.getAttribute('data-expire-action') || 'message'

      // Always stamp the expired state so CSS can react (e.g. swap ticker for
      // expire message, or hide the widget altogether).
      rootEl.setAttribute('data-expired', action)

      if (action === 'message') {
        const expire = rootEl.querySelector('.tms-countdown-timer__expire')
        if (expire) {
          expire.removeAttribute('hidden')
        }
      }

      if (action === 'redirect') {
        const url = rootEl.getAttribute('data-expire-redirect') || ''
        // Defense-in-depth: only allow http(s), mailto, tel, root-relative, or
        // in-page anchors — even though PHP already runs esc_url_raw().
        if (url && /^(https?:|mailto:|tel:|\/|#)/i.test(url)) {
          window.location.assign(url)
        }
      }

      // action === 'hide' is handled purely by CSS via [data-expired="hide"].
    }

    /**
     * Schedule the next tick aligned to the next whole second boundary.
     *
     * @param {Function} fn Tick callback.
     * @returns {number} Timeout id.
     */
    function scheduleNext(fn) {
      const now = Date.now()
      const delay = MS_SECOND - (now % MS_SECOND)
      return window.setTimeout(fn, delay)
    }

    /**
     * Start (or re-start) the countdown loop for a given widget.
     *
     * @param {HTMLElement} rootEl Widget root.
     */
    function startLoop(rootEl) {
      const deadline = resolveDeadline(rootEl)
      if (!deadline) return

      const pad = rootEl.getAttribute('data-pad') === 'yes'
      const reduceMotion = prefersReducedMotion()
      const units = rootEl.querySelectorAll(SELECTOR_UNIT)

      const instance = {
        deadline: deadline,
        pad: pad,
        timeout: null,
        expired: false
      }

      rootEl._tmsCountdownInstance = instance

      function tick() {
        const remaining = instance.deadline - Date.now()

        if (remaining <= 0) {
          // Final paint: zero out every unit.
          units.forEach(function (unit) {
            const key = unit.getAttribute('data-unit') || ''
            paintUnit(unit, key, 0, pad, false)
          })

          onExpire(rootEl, instance)
          return
        }

        const parts = breakdown(remaining)

        units.forEach(function (unit) {
          const key = unit.getAttribute('data-unit') || ''
          if (!(key in parts)) return
          paintUnit(unit, key, parts[key], pad, !reduceMotion)
        })

        instance.timeout = scheduleNext(tick)
      }

      // Kick immediately so the first paint happens without waiting for the
      // next second boundary; subsequent ticks align via scheduleNext().
      tick()
    }

    /**
     * Stop any running loop attached to a widget root (idempotent).
     *
     * @param {HTMLElement} rootEl Widget root.
     */
    function stopLoop(rootEl) {
      const instance = rootEl._tmsCountdownInstance
      if (!instance) return

      if (instance.timeout) {
        window.clearTimeout(instance.timeout)
        instance.timeout = null
      }

      rootEl.removeAttribute('data-expired')
      delete rootEl._tmsCountdownInstance
    }

    /**
     * Bind a single widget instance.
     *
     * @param {HTMLElement} rootEl Widget root.
     */
    function bindInstance(rootEl) {
      // In the Elementor editor the widget is re-rendered on setting changes;
      // always tear down the previous loop before rebuilding.
      stopLoop(rootEl)

      startLoop(rootEl)
    }

    // ------------------------------------------------------------------------
    // Entry.
    // ------------------------------------------------------------------------
    const roots = scope.querySelectorAll(SELECTOR_ROOT)
    if (!roots.length) return

    roots.forEach(bindInstance)
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector('.tms-countdown-timer')) {
      window.Themeasy.countdownTimer.init()
    }
  }

  window.Themeasy.countdownTimer.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(function () {
    window.Themeasy.countdownTimer.boot()
  })

})(window, document)
